import React, {useEffect, useState} from 'react';
import axios from 'axios';
import { API_BASE, MIDTRANS_CLIENT_KEY } from '../config';

function loadMidtrans(clientKey){
  return new Promise((resolve, reject) => {
    if (document.getElementById('midtrans-script')) return resolve();
    const s = document.createElement('script');
    s.id = 'midtrans-script';
    s.src = `https://app.sandbox.midtrans.com/snap/snap.js`; // change to production if needed
    s.setAttribute('data-client-key', clientKey);
    s.onload = () => resolve();
    s.onerror = reject;
    document.body.appendChild(s);
  });
}

export default function Home(){
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(()=>{
    axios.get(`${API_BASE}/products`).then(r=>setProducts(r.data.data || r.data));
  },[])

  function addToCart(p){
    setCart(prev => {
      const found = prev.find(i=>i.product_id===p.id);
      if (found) return prev.map(i=> i.product_id===p.id ? {...i, quantity: i.quantity+1} : i);
      return [...prev, {product_id: p.id, name: p.name, price: p.price, quantity:1}];
    })
  }

  async function checkout(){
    if (!cart.length) return alert('Cart kosong');
    await loadMidtrans(MIDTRANS_CLIENT_KEY);
    const resp = await axios.post(`${API_BASE}/checkout`, {items:cart});
    const token = resp.data.snap_token;
    if (!token) return alert('Gagal membuat transaksi');
    window.snap.pay(token, {
      onSuccess: function(result){
        alert('Pembayaran sukses');
      },
      onPending: function(result){
        alert('Pembayaran pending');
      },
      onError: function(result){
        alert('Pembayaran error');
      }
    });
  }

  return (
    <div style={{fontFamily:'sans-serif'}}>
      <header style={{background:'#f27171', padding:'12px', color:'#000', textAlign:'center'}}>
        <strong>HRSHOPKU BAJU BODO</strong>
      </header>
      <main style={{display:'flex', gap:20, padding:40}}>
        <section style={{flex:1}}>
          <div style={{padding:40}}>
            <h2 style={{fontWeight:300}}>Temukan Dirimu</h2>
            <h1 style={{fontSize:48, margin:0}}>Tampilan & Gaya</h1>
            <button onClick={()=>window.scrollTo({top:400, behavior:'smooth'})} style={{marginTop:24, padding:'12px 24px', background:'#ffb070', border:'none', borderRadius:28}}>Temukan Sekarang</button>
          </div>
        </section>
        <section style={{flex:1, background:'#eee', display:'flex', alignItems:'center', justifyContent:'center'}}>
          <img src="/hero-sample.jpg" alt="hero" style={{maxWidth:'80%'}} />
        </section>
      </main>

      <section style={{padding:'0 40px 80px'}}>
        <h2>Produk</h2>
        <div style={{display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:20}}>
          {products.map(p => (
            <div key={p.id} style={{padding:16, border:'1px solid #ddd'}}>
              <img src={p.image||'/placeholder.png'} alt="p" style={{width:'100%', height:180, objectFit:'cover'}} />
              <h3>{p.name}</h3>
              <p>Rp {p.price}</p>
              <button onClick={()=>addToCart(p)}>Tambah</button>
            </div>
          ))}
        </div>
      </section>

      <aside style={{position:'fixed', right:12, bottom:12, background:'#fff', padding:12, border:'1px solid #ddd'}}>
        <h4>Cart</h4>
        {cart.length===0 && <div>Cart kosong</div>}
        {cart.map(i => (
          <div key={i.product_id}>{i.name} x{i.quantity}</div>
        ))}
        <div style={{marginTop:8}}>
          <button onClick={checkout}>Checkout</button>
        </div>
      </aside>
    </div>
  )
}
